info:
  title: Conduit — Recorte A (usuários, autenticação e perfis)
  description: >
    Subconjunto da RealWorld Conduit API 2.0.0 coberto por esta feature, com as
    chaves de erro fixadas pela spec (FR-004, FR-016, FR-028, FR-032).
    Todas as respostas usam Content-Type application/json; charset=utf-8.
  version: 2.0.0
servers:
  - url: http://localhost:8080/api
paths:
  /users/login:
    post:
      operationId: Login
      requestBody: { $ref: '#/components/requestBodies/LoginUserRequest' }
      responses:
        '200': { $ref: '#/components/responses/UserResponse' }
        '401':
          description: Credenciais inválidas
          content:
            application/json:
              schema: { $ref: '#/components/schemas/GenericErrorModel' }
              example: { errors: { credentials: [invalid] } }
        '422': { $ref: '#/components/responses/GenericError' }
  /users:
    post:
      operationId: CreateUser
      requestBody: { $ref: '#/components/requestBodies/NewUserRequest' }
      responses:
        '201': { $ref: '#/components/responses/UserResponse' }
        '409': { $ref: '#/components/responses/ConflictError' }
        '422': { $ref: '#/components/responses/GenericError' }
  /user:
    get:
      operationId: GetCurrentUser
      security: [ { Token: [] } ]
      responses:
        '200': { $ref: '#/components/responses/UserResponse' }
        '401': { $ref: '#/components/responses/Unauthorized' }
    put:
      operationId: UpdateCurrentUser
      security: [ { Token: [] } ]
      requestBody: { $ref: '#/components/requestBodies/UpdateUserRequest' }
      responses:
        '200': { $ref: '#/components/responses/UserResponse' }
        '401': { $ref: '#/components/responses/Unauthorized' }
        '422':
          description: Validação ou e-mail/username já usado por outro usuário
          content:
            application/json:
              schema: { $ref: '#/components/schemas/GenericErrorModel' }
              example: { errors: { email: [has already been taken] } }
  /profiles/{username}:
    parameters:
      - { name: username, in: path, required: true, schema: { type: string } }
    get:
      operationId: GetProfileByUsername
      description: Autenticação opcional; se o token for enviado, precisa ser válido.
      security: [ {}, { Token: [] } ]
      responses:
        '200': { $ref: '#/components/responses/ProfileResponse' }
        '401': { $ref: '#/components/responses/Unauthorized' }
        '404': { $ref: '#/components/responses/NotFound' }
  /profiles/{username}/follow:
    parameters:
      - { name: username, in: path, required: true, schema: { type: string } }
    post:
      operationId: FollowUserByUsername
      security: [ { Token: [] } ]
      responses:
        '200': { $ref: '#/components/responses/ProfileResponse' }
        '401': { $ref: '#/components/responses/Unauthorized' }
        '404': { $ref: '#/components/responses/NotFound' }
        '422':
          description: Tentativa de seguir a si mesmo
          content:
            application/json:
              schema: { $ref: '#/components/schemas/GenericErrorModel' }
              example: { errors: { profile: [cannot follow yourself] } }
    delete:
      operationId: UnfollowUserByUsername
      security: [ { Token: [] } ]
      responses:
        '200': { $ref: '#/components/responses/ProfileResponse' }
        '401': { $ref: '#/components/responses/Unauthorized' }
        '404': { $ref: '#/components/responses/NotFound' }
components:
  securitySchemes:
    Token:
      type: apiKey
      in: header
      name: Authorization
      description: 'Formato: "Token xxxxxx.yyyyyyy.zzzzzz"'
  requestBodies:
    LoginUserRequest:
      required: true
      content:
        application/json:
          schema:
            type: object
            required: [user]
            properties: { user: { $ref: '#/components/schemas/LoginUser' } }
    NewUserRequest:
      required: true
      content:
        application/json:
          schema:
            type: object
            required: [user]
            properties: { user: { $ref: '#/components/schemas/NewUser' } }
    UpdateUserRequest:
      required: true
      description: Pelo menos um campo é obrigatório. bio/image null apagam o valor.
      content:
        application/json:
          schema:
            type: object
            required: [user]
            properties: { user: { $ref: '#/components/schemas/UpdateUser' } }
  responses:
    UserResponse:
      description: Usuário autenticado
      content:
        application/json:
          schema:
            type: object
            required: [user]
            properties: { user: { $ref: '#/components/schemas/User' } }
    ProfileResponse:
      description: Perfil
      content:
        application/json:
          schema:
            type: object
            required: [profile]
            properties: { profile: { $ref: '#/components/schemas/Profile' } }
    Unauthorized:
      description: Token ausente ("is missing") ou inválido ("is invalid")
      content:
        application/json:
          schema: { $ref: '#/components/schemas/GenericErrorModel' }
          example: { errors: { token: [is missing] } }
    NotFound:
      description: Perfil não encontrado
      content:
        application/json:
          schema: { $ref: '#/components/schemas/GenericErrorModel' }
          example: { errors: { profile: [not found] } }
    ConflictError:
      description: username ou email já cadastrado
      content:
        application/json:
          schema: { $ref: '#/components/schemas/GenericErrorModel' }
          example: { errors: { username: [has already been taken] } }
    GenericError:
      description: Falha de validação
      content:
        application/json:
          schema: { $ref: '#/components/schemas/GenericErrorModel' }
          example: { errors: { email: [can't be blank] } }
  schemas:
    GenericErrorModel:
      type: object
      required: [errors]
      properties:
        errors:
          type: object
          additionalProperties: { type: array, items: { type: string } }
    LoginUser:
      type: object
      required: [email, password]
      properties:
        email: { type: string }
        password: { type: string, format: password }
    NewUser:
      type: object
      required: [email, password, username]
      properties:
        username: { type: string }
        email: { type: string }
        password: { type: string, format: password }
    UpdateUser:
      type: object
      properties:
        email: { type: string }
        password: { type: string }
        username: { type: string }
        bio: { type: [string, 'null'] }
        image: { type: [string, 'null'] }
    User:
      type: object
      required: [bio, email, image, token, username]
      properties:
        email: { type: string }
        token: { type: string }
        username: { type: string }
        bio: { type: [string, 'null'] }
        image: { type: [string, 'null'] }
    Profile:
      type: object
      required: [bio, following, image, username]
      properties:
        username: { type: string }
        bio: { type: [string, 'null'] }
        image: { type: [string, 'null'] }
        following: { type: boolean }

