      description: Token ausente ("is missing") ou inválido ("is invalid")
      content:
        application/json:
          schema: { $ref: '#/components/schemas/GenericErrorModel' }
          example: { errors: { token: [is missing] } }
    NotFound:
      description: Perfil não encontrado
      content:
        application/json:
          schema: { $ref: '#/components/schemas/GenericErrorModel' }
          example: { errors: { profile: [not found] } }
    ConflictError:
      description: username ou email já cadastrado
      content:
        application/json:
          schema: { $ref: '#/components/schemas/GenericErrorModel' }
          example: { errors: { username: [has already been taken] } }
    GenericError:
      description: Falha de validação
      content:
        application/json:
          schema: { $ref: '#/components/schemas/GenericErrorModel' }
          example: { errors: { email: [can't be blank] } }
  schemas:
    GenericErrorModel:
      type: object
      required: [errors]
      properties:
        errors:
          type: object
          additionalProperties: { type: array, items: { type: string } }
    LoginUser:
      type: object
      required: [email, password]
      properties:
        email: { type: string }
        password: { type: string, format: password }
    NewUser:
      type: object
      required: [email, password, username]
      properties:
        username: { type: string }
        email: { type: string }
        password: { type: string, format: password }
    UpdateUser:
      type: object
      properties:
        email: { type: string }
        password: { type: string }
        username: { type: string }
        bio: { type: [string, 'null'] }
        image: { type: [string, 'null'] }
    User:
      type: object
      required: [bio, email, image, token, username]
      properties:
        email: { type: string }
        token: { type: string }
        username: { type: string }
        bio: { type: [string, 'null'] }
        image: { type: [string, 'null'] }
    Profile:
      type: object
      required: [bio, following, image, username]
      properties:
        username: { type: string }
        bio: { type: [string, 'null'] }
        image: { type: [string, 'null'] }
        following: { type: boolean }
